WITH r(role_code, stage, req, sort) AS (VALUES ('OWNER_REP','ON_SITE',1,1),('BUILDING_PLAN_EVALUATOR','ON_SITE',1,2),('CHIEF_FSES','APPROVAL',0,3),('FIRE_MARSHAL','APPROVAL',0,4))
SELECT 'building-plans', r.role_code, r.stage, r.req, r.sort FROM r;







